#include <print>
#include <vector>

int main() {
    std::vector<int> scores = {85, 92, 78, 96, 88};

    int total = 0;
    for (auto s : scores) {
        total += s;
    }
    std::println("总分 = {}", total);
    std::println("平均 = {:.2f}", total * 1.0 / scores.size());

    int good = 0;
    for (auto s : scores) {
        if (s >= 90) {
            good++;
        }
    }
    std::println("90 分以上的有 {} 个", good);

    return 0;
}

